-- v47: isolate privileged engagement functions behind invoker-only public wrappers.
create schema if not exists nagachi_engagement;
revoke all on schema nagachi_engagement from public,anon,authenticated;
grant usage on schema nagachi_engagement to anon,authenticated;
alter function public.nagachi_community_engagement(bigint[]) set schema nagachi_engagement;
revoke all on function nagachi_engagement.nagachi_community_engagement(bigint[]) from public,anon,authenticated;
grant execute on function nagachi_engagement.nagachi_community_engagement(bigint[]) to anon,authenticated;
create function public.nagachi_community_engagement(p_ids bigint[]) returns table(post_id bigint,likes bigint,comments bigint,liked boolean) language sql stable security invoker set search_path='' as $$ select * from nagachi_engagement.nagachi_community_engagement(p_ids) $$;
revoke all on function public.nagachi_community_engagement(bigint[]) from public,anon,authenticated;
grant execute on function public.nagachi_community_engagement(bigint[]) to anon,authenticated;
alter function public.nagachi_community_set_like(bigint,boolean) set schema nagachi_engagement;
revoke all on function nagachi_engagement.nagachi_community_set_like(bigint,boolean) from public,anon,authenticated;
grant execute on function nagachi_engagement.nagachi_community_set_like(bigint,boolean) to authenticated;
create function public.nagachi_community_set_like(p_id bigint,p_enabled boolean) returns boolean language sql security invoker set search_path='' as $$ select nagachi_engagement.nagachi_community_set_like(p_id,p_enabled) $$;
